testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> int:
	var health := 3
	var is_touching_hazard := true
	if is_touching_hazard:
		health -= 1
	return health
",
   "domanda": "Quanto vale `health` alla fine?",
   "spiegazione": "Dato che `is_touching_hazard` è vero, viene eseguito il blocco `if`, togliendo 1 a `health` (che passa da 3 a 2)."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var velocity_y := -150.0
	var state := "IDLE"
	if velocity_y < 0.0:
		state = "JUMP"
	else:
		state = "FALL"
	return state
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Poiché `velocity_y` è negativo (-150.0), la condizione `velocity_y < 0.0` è vera, quindi `state` diventa "JUMP"."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var area_group := "hazards"
	var is_dead := false
	if area_group == "hazards" or area_group == "enemies":
		is_dead = true
	return is_dead
",
   "domanda": "Che valore restituisce `run()`?",
   "spiegazione": "L'istruzione `if` controlla se il gruppo è "hazards" oppure "enemies". Visto che `area_group` è "hazards", la prima parte dell'operatore `or` è vera e `is_dead` diventa `true`."
  },
  {
   "codice": "extends RefCounted


func run() -> Vector2:
	var respawn_point := Vector2(100.0, 200.0)
	var current_pos := Vector2(500.0, 50.0)
	current_pos = respawn_point
	return current_pos
",
   "domanda": "Quanto vale `current_pos` alla fine?",
   "spiegazione": "Alla variabile `current_pos` viene assegnato direttamente il valore della variabile `respawn_point`, cioè `Vector2(100.0, 200.0)`."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var coyote_timer := 0.15
	var delta := 0.05
	coyote_timer -= delta
	return coyote_timer
",
   "domanda": "Quanto vale `coyote_timer` alla fine?",
   "spiegazione": "`coyote_timer` parte da 0.15 e viene sottratto `delta` (0.05). Il risultato è 0.10."
  }
 ]
